import importlib.util,sys,time
from pathlib import Path
import numpy as np
from scipy.stats import spearmanr
mods=[]
for path in sys.argv[1:]:
 spec=importlib.util.spec_from_file_location('m'+str(len(mods)),path)
 m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m);mods.append((path,m))
for p in sorted(Path('/workspace/environment/public_assets/dev').glob('*.npz')):
 z=np.load(p); args=(z['x'],z['y'],z['r'],z['ry'],int(z['seed']))
 cache=Path('/tmp/research_history/'+p.stem+'_canonical.npy')
 if cache.exists():target=np.load(cache)
 else:
  target=mods[0][1].value(*args);np.save(cache,target)
 for path,m in mods[1:]:
  t=time.perf_counter();out=m.value(*args);dt=time.perf_counter()-t
  n=len(out);a=np.argsort(-out,kind='stable')[:n//4];b=np.argsort(-target,kind='stable')[:n//4]
  nr=np.sqrt(np.mean((out-target)**2))/target.std();rho=spearmanr(out,target).statistic;top=len(set(a)&set(b))/(n//4)
  print(p.stem,Path(path).parent.name,'time',round(dt,4),'nrmse',nr,'rho',rho,'top',top,'valid',nr<=.01 and rho>=.999 and top>=.98,flush=True)
import subprocess,sys,json
from pathlib import Path
import numpy as np
paths=sys.argv[1:]
child='''import importlib.util,sys,time,json
import numpy as np
p=sys.argv[1];spec=importlib.util.spec_from_file_location('m',p);m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
z=np.load('/workspace/environment/public_assets/dev/seed_303_gaussian_016.npz');args=(z['x'],z['y'],z['r'],z['ry'],int(z['seed']))
t=time.perf_counter();v=m.value(*args);dt=time.perf_counter()-t
print(json.dumps({'time':dt,'std':float(v.std())}))
'''
times=[[] for _ in paths]
for t in range(8):
 for k in (range(len(paths)) if t%2==0 else range(len(paths)-1,-1,-1)):
  z=json.loads(subprocess.run([sys.executable,'-c',child,paths[k]],check=True,capture_output=True,text=True).stdout)
  times[k].append(z['time'])
for p,ts in zip(paths,times):print(Path(p).parent.name,'median',np.median(ts),'times',ts,flush=True)
